effect.shader:
// s_pixelsort v4 - Ultra Fidelity AE Logic

#define PI 3.14159265359

float getVal(vec3 col, int type) {
    if (type == 1) return col.r;
    if (type == 2) return col.g;
    if (type == 3) return col.b;
    return dot(col, vec3(0.2126, 0.7152, 0.0722)); // Monochrome/Luma
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 uv = acScreenNorm;
    float rad = sortAngle * (PI / 180.0);
    vec2 dir = vec2(cos(rad), sin(rad));

    // Seed influence on the base sampling pattern
    vec2 seedOff = vec2(hash(vec2(seed, seed * 0.5)));

    vec4 src = texture2DCv(inputImg.texture, uv);
    float val = getVal(src.rgb, int(sortType));

    float soft = max(softenThreshold, 0.001);
    float tLow = threshold - soft * 0.5;
    float tHigh = threshold + soft * 0.5;

    float weight = (sortDirection == 0) ? smoothstep(tLow, tHigh, val) : 1.0 - smoothstep(tLow, tHigh, val);

    vec3 res = src.rgb;

    if (weight > 0.01) {
        // Intense search for high-contrast streaks (Sapphire "Smear" style)
        float stepSize = 0.0012; 
        int iterations = 80; // Maximum depth for thick glitch bars

        vec3 streakCol = src.rgb;
        float extremeVal = (sortDirection == 0) ? -1.0 : 2.0;

        for (int i = 1; i < 80; i++) {
            float d = float(i) * stepSize;
            vec2 sampleUv = uv - dir * d;

            if(sampleUv.x < 0.0 || sampleUv.x > 1.0 || sampleUv.y < 0.0 || sampleUv.y > 1.0) break;

            vec4 sampleCol = texture2DCv(inputImg.texture, sampleUv);
            float sampleVal = getVal(sampleCol.rgb, int(sortType));

            bool inRange = (sortDirection == 0) ? (sampleVal > tLow) : (sampleVal < tHigh);

            if (inRange) {
                if (sortDirection == 0) {
                    if (sampleVal > extremeVal) {
                        extremeVal = sampleVal;
                        streakCol = sampleCol.rgb;
                    }
                } else {
                    if (sampleVal < extremeVal) {
                        extremeVal = sampleVal;
                        streakCol = sampleCol.rgb;
                    }
                }
            } else {
                break;
            }

            // Break based on Randomly Restart + Seed + Temporal Jitter
            if (randomlyRestart > 0.0 && hash(sampleUv + seedOff + acTime * 0.01) < randomlyRestart * 0.2) {
                break;
            }
        }

        if (blurMatte > 0.0) {
            vec4 blurSample = texture2DCv(inputImg.texture, uv + dir * 0.005 * blurMatte);
            streakCol = mix(streakCol, blurSample.rgb, blurMatte * 0.4);
        }

        res = mix(src.rgb, streakCol, weight);
    }

    res = mix(res, src.rgb, mixWithSource);
    gl_FragColor = vec4(res, src.a);
}
